function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400);}
function sound(kind='click'){if(!settings.sound)return;try{audioContext??=new AudioContext();audioContext.resume();const t=audioContext.currentTime;const notes=kind==='good'?[523,659,784]:kind==='bad'?[330,247]:[440];notes.forEach((f,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(audioContext.destination);g.gain.setValueAtTime(0,t+i*.09);g.gain.linearRampToValueAtTime(.045,t+i*.09+.015);g.gain.exponentialRampToValueAtTime(.001,t+i*.09+.17);o.start(t+i*.09);o.stop(t+i*.09+.2);});}catch{}}
