function openDialog(title,body,wide=false){closeGameChoice();closeInfo();if(!dialog.open)dialogFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title" tabindex="-1">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;dialog.classList.toggle('wide',wide);if(!dialog.open)dialog.showModal();prepareDialogContent(dialog);enhanceGameControls(dialog);dialog.querySelector('#dialog-title')?.focus({preventScroll:true});dialog.querySelector('.dialog-body').scrollTop=0;}
async function runChapterTransition({settleDay=false}={}){
 if(chapterRunning||!lifeChapter(state))return;
 if(settleDay&&!canSettleChapterDay(state)){notify('先处理眼前的事件或健康问题，再结算生活。');return;}
 if(!settleDay&&!stagePlan(state)){detailedDay=false;tab='life';closeDialog();render();notify('先选择这段时间的生活重心。');return;}
 chapterRunning=true;chapterStopRequested=false;marketDesk=null;tab='life';detailedDay=false;
 const reduced=settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches;
 let trip=chapterTrip(state),stop=null,lastShotAt=performance.now(),shotIndex=0;
 try{
  openDialog('日子慢慢过去',renderChapterMontage(state,trip,guideContext(),reduced),true);
  for(let i=0;i<90;i++){
   // Yield before every bounded batch, including the first, so Stop and Escape stay usable.
   await new Promise(resolve=>setTimeout(resolve,40));
   if(chapterStopRequested){stop=stopChapterTrip(trip);break;}
   const step=advanceChapterStep(state,catalog,trip,{settleDay});trip=step.trip;stop=step.stop;
   state=updateJourney(state,step.state);persist();
   if(savingError){stop={kind:'save',reason:'自动保存未成功，已停止过渡。请先导出存档。'};break;}
   const date=dialog.querySelector('.chapter-date');
   if(date)date.innerHTML=`${esc(trip.from)} → ${esc(trip.to)}<strong>已度过 ${trip.days} 天</strong>`;
   if(!reduced&&performance.now()-lastShotAt>1100){shotIndex=(shotIndex+1)%3;lastShotAt=performance.now();dialog.querySelectorAll('[data-chapter-shot]').forEach((image,i)=>image.hidden=i!==shotIndex);} 
   if(stop)break;
  }
  stop??={kind:'pause',reason:'先停在这里，稍后可以接着过日子。'};
 }catch(error){stop={kind:'error',reason:'过渡已停下：'+error.message};}
 finally{
  chapterRunning=false;
  trip={...trip,...stop};state.chapterSummary=trip;persist();render();
  if(state.phase!=='ended')openDialog(settleDay?'今天的结算':'阶段进展',renderChapterReceipt(state,trip,guideContext()),true);
 }
}
