function beginNewRun(options,slot){detailedDay=false;marketDesk=null;closeDialog();activeSlot=slot;tab='life';commit(createPlayableRun(options,catalog));sound('good');scrollGameTo(0);}
function jobDialog(selectedId){openDialog(hasSalariedJob(state)?'换份工作 · 比较机会':'找份工作 · 比较机会',renderJobOpportunities(state,{esc,money},selectedId),true);if(selectedId)dialog.querySelector(`[data-action=job-select][data-id="${CSS.escape(selectedId)}"]`)?.focus({preventScroll:true});}
function runAction(action,personId=null){
 if(action.type==='seek_job'||action.type==='day_activity'&&action.choice==='job_hunt'){jobDialog();return;}
 const fromRescue=Boolean(dialog.querySelector('.rescue-menu,.rescue-back'));
 const a=available(action);if(!a.allowed){notify(a.reason);return;}
 const focus=captureTradeFocus();
 const before=state,anchor=document.querySelector('.market-desk'),top=anchor?.getBoundingClientRect().top;
 const drafts=[...document.querySelectorAll('#desk-order input,#desk-order select,#gamble-form input,#gamble-form select')].filter(e=>e.name).map(e=>({name:e.name,value:e.value,type:e.type,checked:e.checked}));
 const next=act(state,action,catalog);if(next.lastResult?.error){notify(next.lastResult.error);return;}
 const statChanges=Object.keys(before.stats).filter(k=>before.stats[k]!==next.stats[k]).map(key=>({key,value:next.stats[key]-before.stats[key]}));next.lastResult.statChanges=statChanges;
 const inline=(action.type==='life_choice'&&action.scene==='consumption')||INLINE_ACTIONS.has(action.type)&&!needsMajorReceipt(before,next,action);
 if(personId)peopleView={runId:state.id,selectedId:personId,filter:'all',feedback:{personId,title:next.lastResult.title,text:next.lastResult.text,trust:relation(next,personId)-relation(before,personId),actions:before.actionPoints-next.actionPoints,cash:next.cash-before.cash}};
 closeDialog();commit(updateJourney(before,next,action));sound();if(state.phase==='ended')return;
 const night=inline?nightTransitionData(before,state,action):null;
 if(night)playNightTransition(night,{reduced:settings.reduced,onFinish:()=>{maybeRescueDialog();if(!dialog.open)document.querySelector('.daily-operation-dock .day-choices button:not(:disabled),.desk-quickbar [data-action=life-continue],.bottom-nav [aria-current=page]')?.focus({preventScroll:true});}});else playActionMotion(action);
 if(state.age<18&&tab==='life'&&childhoodActivities(state).some(a=>a.type===action.type)){document.querySelector('.childhood-operation-dock [data-type="'+action.type+'"]:not(:disabled),.childhood-operation-dock [data-action=life-continue]')?.focus({preventScroll:true});return;}
 if(personId&&tab==='people'){focusPersonFeedback();return;}
 if(inline){
  notify(receiptSummary(state)?.brief||next.lastResult.title);
  for(const d of drafts){const els=[...document.querySelectorAll('#desk-order input,#desk-order select,#gamble-form input,#gamble-form select')].filter(e=>e.name===d.name);for(const e of els){if(e.type==='radio'){if(e.value===d.value)e.checked=d.checked;}else if(e.type==='checkbox')e.checked=d.checked;else if(e.tagName!=='SELECT'||[...e.options].some(o=>o.value===d.value))e.value=d.value;}}
  document.querySelectorAll('#desk-order,#gamble-form').forEach(form=>updateDeskForm(form,state,{money,esc}));
  const nextAnchor=document.querySelector('.market-desk');if(top!==undefined&&nextAnchor)scrollGameBy(nextAnchor.getBoundingClientRect().top-top);
  restoreTradeFocus(focus);if(fromRescue&&getSurvivalStatus(state).active)rescueDialog();return;
 }
 const r=state.lastResult;const familyArt=action.type==='family_wedding'?(state.age<36?'family-wedding':'family-budget'):action.type==='life_choice'&&action.scene==='family'?({birth:state.age<36?'family-newborn':'family-newborn-hospital',childcare:'family-childcare'})[before.familyLife?.pending]:null;openDialog(r?.title||'安排好了',`${familyArt?renderEventArt('life:family',guideContext(),familyArt):''}<p class="result-dialog-text">${esc(r?.text)}</p>${renderChanges(r?.changes)}${renderStatChanges(statChanges)}<div class="dialog-footer"><span>精力 ${state.actionPoints} / 2 · 市场 ${tradingState(state).energy} 次操作</span>${fromRescue&&getSurvivalStatus(state).active?'<button class="button" data-action="rescue-options">继续安排生活费</button>':''}<button class="button primary" data-action="close-dialog">继续 ${icon('check')}</button></div>`);
}

const centsFromInput=form=>{const raw=String(new FormData(form).get('amount')||'');if(!/^\d+(\.\d{1,2})?$/.test(raw))throw Error('请输入大于零的金额，最多两位小数。');const cents=Math.round(Number(raw)*100);if(!Number.isSafeInteger(cents)||cents<=0)throw Error('这个金额超出了可用范围。');return cents;};
function amountField({value=1000,min=1,max,label='投入金额',help=''}){return `<div class="field"><label for="amount">${label} <span>元</span></label><input id="amount" name="amount" type="number" inputmode="decimal" value="${value}" min="${min}" ${max!==undefined?`max="${max}"`:''} step="0.01" required>${help?`<small>${help}</small>`:''}</div>`;}
function confirmAvailability(form,action){const preview=form.querySelector('.order-preview');if(preview){const spend=action.amount||0;const html=`<strong>本单金额</strong><span>本次投入 <b>${money(spend)}</b></span>${renderCashBudget(state,{...guideContext(),verb:tradeTerms(action.product).open},spend)}${action.financed?`<span>新增按揭本金约 <b>${money(Math.round(spend/0.3)-spend)}</b></span>`:''}<small>用 1 点精力 · 收益到期结算</small>`;if(preview._html!==html){preview.innerHTML=html;preview._html=html;}}const allowed=available(action);const errorEl=form.querySelector('.form-error');const submit=form.querySelector('[type=submit]');errorEl.textContent=allowed.reason||'';submit.disabled=!allowed.allowed;return allowed.allowed;}
function investDialog(product){if(product==='housing'){marketDesk='housing';deskSelection=null;tab='market';render();return;}const access=getMarketAccess(state,product);if(!access.unlocked){marketRulesDialog(product);return;}const meta=PRODUCTS[product],info=products.find(x=>x[0]===product),m=metric();if(!meta)return;
 const amount=Math.max(meta.min/100,Math.min(Math.floor(state.cash/100*.2),10000));
 openDialog(`${tradeTerms(product).open} · ${meta.name}`,`<form id="invest-form" data-product="${product}"><p class="dialog-intro">${esc(info[3])}</p>${amountField({value:amount,min:meta.min/100,max:state.cash/100,label:tradeTerms(product).amount,help:`本次最低投入 ${money(meta.min)}。一个投资动作占用 1 点精力。`})}${['option','option_short','futures'].includes(product)?`<div class="field-pair"><div class="field"><label for="direction">${product==='futures'?'持仓方向':'期权类型'}</label><select id="direction" name="direction"><option value="long">${directionLabel(product,'long')}</option><option value="short">${directionLabel(product,'short')}</option></select></div>${product==='futures'?'<div class="field"><label for="leverage">杠杆倍数</label><select id="leverage" name="leverage"><option value="2">2 倍</option><option value="5">5 倍</option><option value="10">10 倍</option></select></div>':''}</div>`:''}${['stock','bond','crypto','futures'].includes(product)?`<div class="field"><label for="underlying">市场敞口</label><select id="underlying" name="underlying">${({stock:[['stock','综合股票'],['GME','游戏零售股原型']],bond:[['bond','一般债券'],['UK_GILT','英国国债原型']],crypto:[['crypto','加密资产'],['UST','算法稳定币原型'],['LUNA','算法生态币原型'],['FTX','平台托管资产原型']],futures:INSTRUMENTS.futures.map(i=>[i.id,i.name])}[product]).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><small>特殊历史冲击只作用在相关敞口。</small></div>`:''}${product==='housing'?'<label class="check-field"><input type="checkbox" name="financed">以本次金额作为 30% 首付，申请按揭</label><p class="field-help">游戏按揭年利率 4.5%、20 年期限，审批需要收入、信用与正常履约。剩余 70% 计入债务。</p>':''}<div class="order-preview" aria-live="polite"></div><div class="term-note">${esc(meta.description)}${product==='futures'?' 强平按逐仓保证金结算；本金若来自贷款，借款继续存在。':product==='option_short'?' 卖方收取的权利金暂存至到期，极端履约缺口会转为债务。':product==='option'?' 下一回合到期，最多损失本次权利金。':product==='angel'?' 基础锁定 6 回合，股权退出后才成为现金。':''}</div><p class="form-error" role="alert"></p><button type="submit" class="button primary full">${tradeTerms(product).open} ${icon('arrow')}</button></form>`);updateForm(dialog.querySelector('form'));
}
// Keep the next reading position and keyboard path inside the new story.
function focusStory(){
 const birth=document.querySelector('#birth-title');
 const panel=document.querySelector('.story-panel');
 const target=birth||(state.phase==='result'?panel?.querySelector('h2'):panel);
 if(!target)return;
 target.tabIndex=-1;
 if(target===panel){target.setAttribute('role','region');target.setAttribute('aria-label',panel.querySelector('h2')?.textContent||'眼前的故事');}
 target.focus({preventScroll:true});
 target.scrollIntoView({block:target===panel?'start':'nearest',behavior:'instant'});
}
function continueLife(skipMarket=false,fastOnly=false){
 if(skipMarket&&lifeChapter(state)&&!getLegalStatus(state).inPrison){detailedDay=false;tab='life';marketDesk=null;closeDialog();render();return;}
 if(state.age<18&&state.phase!=='event'){closeDialog();commit(continueChildhood(state,catalog));focusStory();return;}
 const p=continuation(state,{skipMarket,market:tab==='market'?marketDesk:null});
 if(p.kind==='health'){rescueDialog();return;}
 if(p.kind==='daily'){dailyRoutine();notify('先选完当前事件，时间才会继续。');return;}
 if(p.kind==='story'){closeDialog();tab='life';render();focusStory();return;}
 if(p.kind==='result'){closeDialog();commit(continueStory(state,catalog));focusStory();return;}
 if(p.kind==='life'){openLifeScene();return;}
 if(p.kind==='behavior'){behaviorScene();return;}
 if(p.kind==='action'){
  if(p.action.type==='live_days'){detailedDay=false;tab='life';closeDialog();render();return;}
  if(fastOnly&&p.action.type!=='live_days'&&getSurvivalStatus(state).active){rescueDialog();notify('生活费不足，先安排周转；时间没有推进。');return;}
  const r=routineState(state),returnToDay=tab==='market'&&p.action.type==='day_next'&&(marketActivity(r.choices[r.stage])||r.stage===7);
  runAction(p.action);
  if(returnToDay&&state.phase==='planning'){tab='life';closeDialog();render();dailyRoutine();}
  if(p.action.type==='live_days'&&Number.isInteger(state.lastResult?.days))notify(`${state.lastResult.days?`已推进 ${state.lastResult.days} 天`:'快进已暂停'}。${receiptSummary(state)?.brief||''}`);
  if(state.dayRoutine?.pending&&tab==='life')dailyRoutine();return;
 }
 if(p.kind==='period'){dispatch({dataset:{action:'advance-period'}});const next=document.querySelector(state.phase==='event'?'.choice:not([disabled])':'[data-action=life-continue]');next?.focus({preventScroll:true});next?.scrollIntoView({block:'center',behavior:'instant'});}
}
function dailyRoutine(){detailedDay=true;render();if(tab==='life'&&dailyScene(state)){closeDialog();const dock=document.querySelector('.life-clockbar'),event=dock?.querySelector('#daily-event-title'),target=event||dock?.querySelector('.day-choices button:not(:disabled)');if(dock){dock.scrollTop=0;dock.classList.add('is-highlighted');setTimeout(()=>dock.classList.remove('is-highlighted'),1800);}target?.focus({preventScroll:true});target?.scrollIntoView({block:'nearest',behavior:'instant'});return;}openDialog(state.dayRoutine?.pending?'当前事件':'今天怎么过',renderDailyRoutine(state,{esc,icon,money}));const timeline=dialog.querySelector('.day-timeline'),current=timeline?.querySelector('[aria-current]');if(current){const r=current.getBoundingClientRect(),t=timeline.getBoundingClientRect();timeline.scrollLeft+=r.left-t.left-(timeline.clientWidth-r.width)/2;}}
let pendingMarketEntry=null;
function offerMarketWelcome(entry){const intro=marketWelcome(state,entry.product);if(!intro)return false;pendingMarketEntry={...entry};openDialog(intro.title,renderMarketWelcome(state,entry.product,{esc}));return true;}
function openDailyMarket(){
 closeDialog();const r=routineState(state),night=r.stage>=6;
 const preferred=night?'crypto':'stock';
 if(getMarketAccess(state,preferred).unlocked&&offerMarketWelcome({product:preferred}))return;
 marketDesk=getMarketAccess(state,preferred).unlocked?preferred:null;
 marketReturn={top:0,product:marketDesk};deskSelection=null;cryptoMode='spot';tab='market';render();scrollGameTo(0);
 document.querySelector('.desk-quickbar [data-action=life-continue],.period-console [data-action=life-continue]')?.focus({preventScroll:true});
}
function behaviorHub(){openDialog('状态与消息',renderBehaviorHub(state,{money,esc,icon}),true);}
function behaviorScene(){const b=getBehaviorStatus(state);if(b.pending)openDialog(BEHAVIOR_EVENTS[b.pending].title,renderBehaviorScene(state,{money,esc,icon}));else behaviorHub();}
function debtCalendarDialog(){openDialog('还款日历',renderDebtCalendar(state,{money,esc,icon}),true);}
function loansDialog(kind){
 const m=metric(),offers=getLoanOffers(state),selected=offers.find(o=>o.kind===kind)||offers.find(o=>o.allowed)||offers[0];
 openDialog('借钱周转',`<form id="loan-form"><p class="dialog-intro">申请用 1 点精力；未获批不扣费。</p><div class="dialog-budget"><span>稳定月收入 <b>${money(m.monthlyIncome,true)}</b></span><span>现有债务 <b>${money(m.debt,true)}</b></span></div><div class="field"><label for="loan-kind">向谁周转</label><select id="loan-kind" name="kind">${offers.map(o=>`<option value="${o.kind}" ${o.kind===selected.kind?'selected':''}>${esc(o.label)} · ${o.aprBps?`年化 ${o.aprBps/100}%`:'无息'} · ${o.months} 个月</option>`).join('')}</select></div><p id="loan-conditions" class="field-help"></p>${renderLoanAmount(selected,{money})}<div id="loan-estimate" class="loan-receipt" aria-live="polite"></div><p id="loan-consequence" class="term-note"></p><p class="field-help">30 天后开始按月还款，具体日期见还款日历。</p><p class="form-error" role="alert"></p><button type="submit" class="button primary full">确认借款 ${icon('arrow')}</button></form><div class="dialog-footer ${getSurvivalStatus(state).active?'rescue-back':''}">${getSurvivalStatus(state).active?'<button class="text-button" data-action="rescue-options">← 返回生活费安排</button>':'<button class="text-button" data-action="life-action" data-type="gig">去做零工</button>'}</div>`);updateForm(dialog.querySelector('form'));
}
function repayDialog(id){const m=metric(),d=id&&state.debts.find(d=>d.id===id);if(id&&!d){notify('这笔债务已经还完。');return;}const owed=d?d.principal+d.interest:m.debt;openDialog(d?`${isLivingBill(d)?'支付账单':'偿还'} · ${livingBillName(d.name)}`:'偿还欠款',`<form id="repay-form" ${d?`data-id="${esc(d.id)}"`:''}><div class="dialog-budget"><span>手头现金 <b>${money(state.cash,true)}</b></span><span>${d&&isLivingBill(d)?'待付金额':'剩余本息'} <b>${money(owed,true)}</b></span></div>${amountField({value:Math.min(owed,state.cash)/100,max:Math.min(owed,state.cash)/100,label:d&&isLivingBill(d)?'本次支付':'本次还款',help:d&&isLivingBill(d)?'支付已发生的生活费用，不另收利息。':d?'只偿还这笔债务，先付利息再减本金；未付清到期款仍算逾期。':'优先偿还逾期与高利率债务；先付利息，再减本金。'})}<p class="form-error" role="alert"></p><button type="submit" class="button primary full">${d&&isLivingBill(d)?'确认支付':'确认还款'} ${icon('check')}</button></form>`);updateForm(dialog.querySelector('form'));}

function businessDialog(){const a=available({type:'business_run'});openDialog('开店做生意',`<p class="dialog-intro">经营利润已扣租金等开销，生意差时可能亏损。</p>${state.businesses.length?`<div class="business-existing">${state.businesses.map(b=>`<article><div><strong>${esc(b.name)}</strong><small>账面 ${money(b.value,true)} · 月净现金流 ${money(b.monthlyProfit,true)}</small>${available({type:'sell',id:b.id}).allowed?'':`<small class="business-exit-reason">${esc(available({type:'sell',id:b.id}).reason)}</small>`}</div><button class="text-button" data-action="sell" data-id="${esc(b.id)}" ${available({type:'sell',id:b.id}).allowed?'':'disabled'}>转让</button></article>`).join('')}<button class="button full" data-action="life-action" data-type="business_run" ${a.allowed?'':'disabled'}>照看生意 · 1 点精力</button>${a.reason?`<p class="field-help">${esc(a.reason)}</p>`:''}</div>`:''}<form id="business-form"><div class="field"><label for="shop-name">小店名字</label><input id="shop-name" name="businessName" maxlength="24" value="${esc(state.name)}的小店"></div>${amountField({value:5000,min:3000,max:Math.max(3000,state.cash/100),label:'启动本金',help:`当前现金 ${money(state.cash,true)}；至少 ¥3,000。`})}<p class="form-error" role="alert"></p><button type="submit" class="button primary full">确认开店 ${icon('sun')}</button></form>`);updateForm(dialog.querySelector('form'));}
function actionFromForm(form){const d=new FormData(form);switch(form.id){case 'invest-form':return {type:'invest',product:form.dataset.product,amount:centsFromInput(form),direction:d.get('direction')||'long',leverage:Number(d.get('leverage')||2),underlying:d.get('underlying')||undefined,financed:d.has('financed')};case 'loan-form':return {type:'borrow',kind:d.get('kind'),amount:centsFromInput(form)};case 'repay-form':return {type:'repay',id:form.dataset.id||undefined,amount:centsFromInput(form)};case 'business-form':return {type:'business_start',name:String(d.get('businessName')||'自己的小店').slice(0,24),amount:centsFromInput(form)};}}
function updateForm(form){if(form?.id==='living-plan-form'){updateLivingPlan(form,state,{money});return;}if(form?.id==='child-market-form'){updateChildForm(form,state,{money});return;}if(form?.matches('#desk-order,#gamble-form,.desk-manage-form')){updateDeskForm(form,state,{money,esc});return;}if(!form||!['invest-form','loan-form','repay-form','business-form'].includes(form.id))return;try{const action=actionFromForm(form);confirmAvailability(form,action);if(form.id==='loan-form'){const o=getLoanOffer(state,action.kind,action.amount);updateLoanPresets(form,o.cap,action.amount,{money});form.querySelector('#loan-conditions').textContent=`当前额度上限 ${money(o.cap)} · 年化 ${o.aprBps/100}% · ${o.months} 个月 · 审批成功率约 ${Math.round(o.approval*100)}%（满足条件后）`;form.querySelector('#loan-estimate').innerHTML=`<h3>借款明细</h3><dl><div><dt>实际到账</dt><dd>${money(o.net)}</dd></div><div><dt>先扣费用</dt><dd>${money(o.fee)}</dd></div><div><dt>新增本金</dt><dd>${money(o.principal)}</dd></div><div><dt>首月预计还款</dt><dd>${money(o.firstPayment)}</dd></div></dl>`;form.querySelector('#loan-consequence').textContent=o.consequence+' 申请成功后压力 +4。';}}catch(e){form.querySelector('.form-error').textContent=e.message;form.querySelector('[type=submit]').disabled=true;}}
function savesDialog(){openDialog('人生档案',`<p class="dialog-intro">自动保存在此浏览器。换设备或清理数据前，请导出备份。</p><div class="save-slots">${listSlots().map(x=>`<article class="save-slot ${state&&x.slot===activeSlot?'current':''}"><div class="save-slot-number">0${x.slot+1}</div><div class="save-slot-info"><h3>${x.state?esc(x.state.name):x.error?'档案暂时无法读取':'空存档'} ${state&&x.slot===activeSlot?'<span class="tag">当前</span>':''}</h3><p>${x.state?`${ageText(x.state.age)} · ${esc(x.state.familyName)} · ${x.state.phase==='ended'?'人生后记':'第 '+(x.state.turn+1)+' 回合'}`:x.error?esc(x.error):'还没有存档。'}</p><div class="save-slot-buttons">${x.state?`<button class="button small" data-action="load-slot" data-slot="${x.slot}">继续</button><button class="text-button" data-action="export-slot" data-slot="${x.slot}">${icon('download')} 导出</button>`:''}${state?`<button class="text-button" data-action="save-to-slot" data-slot="${x.slot}">存到这里</button>`:''}<button class="text-button" data-action="import" data-slot="${x.slot}">${icon('upload')} 导入</button>${x.state||x.error?`<button class="text-button danger-text" data-action="delete-slot" data-slot="${x.slot}">删除</button>`:''}</div></div></article>`).join('')}</div><div class="dialog-footer"><button class="text-button" data-action="playtest">记录试玩感受</button><span>共 ${collection.endings.length} / ${catalog.endings.length} 种已见后记</span><button class="text-button" data-action="ending-collection">翻看后记 ${icon('book')}</button></div>`,true);}
function settingsDialog(){openDialog('游戏设置',`<div class="setting-row"><div><strong>轻声音效</strong><p>选择和成交时播放提示音。</p></div><label class="switch"><input type="checkbox" data-setting="sound" ${settings.sound?'checked':''} aria-label="轻声音效"><span></span></label></div><div class="setting-row"><div><strong>减少动态效果</strong></div><label class="switch"><input type="checkbox" data-setting="reduced" ${settings.reduced?'checked':''} aria-label="减少动态效果"><span></span></label></div><div class="setting-links"><button class="button full" data-action="help">${icon('help')} 玩法手册</button>${state?`<button class="button full" data-action="home">${icon('home')} 回到标题画面</button>`:''}</div><p class="workspace-footnote">v1.55.0 · 单机游戏 · 交易使用虚拟资金</p>`);}
function helpDialog(){openDialog('玩法手册',renderHelp(catalog.endings.length));}
function historyDetail(id){const h=catalog.history.find(x=>x.id===id);if(!h)return;let href='';try{const u=new URL(h.source_url);if(u.protocol==='https:'||u.protocol==='http:')href=u.href;}catch{}openDialog(h.name,`<span class="tag">真实历史原型 · ${esc(h.date)}</span><p class="result-dialog-text">${esc(h.fact)}</p><div class="term-note"><strong>影响的市场</strong><p>${esc(h.shock_channels.join('、'))}。${state?.mode==='remix'?'本局出现时间随机。':'历史模式按记载年份触发。'}</p></div>${href?`<a class="button full" href="${esc(href)}" target="_blank" rel="noopener noreferrer">查阅事实来源 ${icon('arrow')}</a>`:''}`);}
function endingCollection(){const seen=new Set(collection.endings);openDialog(`${catalog.endings.length} 种人生后记`,`<p class="dialog-intro">已点亮 ${seen.size} / ${catalog.endings.length} 种。</p>${renderRunComparison(collection,guideContext())}<div class="ending-grid">${catalog.endings.map((e,i)=>`<button class="ending-item ${seen.has(e.id)?'unlocked':''}" data-action="ending-detail" data-id="${e.id}" ${seen.has(e.id)?'':'disabled'}><span>${String(i+1).padStart(2,'0')}</span><strong>${seen.has(e.id)?esc(e.title):'尚未解锁'}</strong>${icon(seen.has(e.id)?'book':'lock')}</button>`).join('')}</div>`,true);}
function endingDetail(id){const e=catalog.endings.find(x=>x.id===id);if(!e)return;openDialog(e.title,`<p class="ending-prose">${esc(e.epilogue)}</p><div class="term-note">后来，也许会……<p>${e.open_directions.map(esc).join('；')}。</p></div>`);}
function downloadFile(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportSlot(slot){const s=loadSlot(slot);if(!s){notify('这个档案还没有内容。');return;}downloadFile(`中国式赌狗_${s.name}_${ageText(s.age)}.json`,JSON.stringify(encodeSave(s),null,2));notify('人生档案已导出。');}
function exportJournal(){if(!state)return;const m=metric();const text=`# ${state.name}的一生\n\n出身：${state.familyName}\n年龄：${ageText(state.age)}\n命运种子：${state.seed}\n净资产：${money(m.netWorth)}\n现金：${money(state.cash)}\n债务：${money(m.debt)}\n${state.ending?'后记：'+state.ending.title+'\n\n'+state.ending.epilogue:''}\n\n${auditText(state,money)}\n\n${onlineGamblingText(state,money)}\n\n${cryptoLifeText(state,money)}\n\n${schemeLifeText(state,money)}\n\n${state.logs.map(l=>`## ${ageText(l.age??state.age)} · ${l.title}\n\n${l.text}`).join('\n\n')}\n`;
 downloadFile(`中国式赌狗_${state.name}_人生小记.md`,text,'text/markdown;charset=utf-8');notify('人生小记已留下。');}
let pendingConfirm=null,importSlot=0;
function confirmDialog(title,text,callback,label='确认'){pendingConfirm=callback;openDialog(title,`<p class="dialog-intro">${esc(text)}</p><div class="dialog-footer"><button class="button" data-action="close-dialog">再想想</button><button class="button primary" data-action="confirmed">${esc(label)}</button></div>`);}
function loadGame(slot){marketDesk=null;const loaded=loadSlot(slot);if(!loaded){notify('这个档案还没有内容。');return;}closeDialog();activeSlot=slot;tab='life';detailedDay=false;commit(loaded);scrollGameTo(0);notify('这一生，继续。');}
function dispatch(button){if(isNightTransitionActive()||chapterRunning&&!['chapter-stop','close-dialog'].includes(button.dataset.action))return;const d=button.dataset,fromRescue=Boolean(button.closest?.('.rescue-menu'));switch(d.action){
 case 'info-open':showInfo(button,infoContent(d.info,state,products,guideContext()));break;
 case 'close-dialog':closeDialog();break;
 case 'confirmed':{const fn=pendingConfirm;pendingConfirm=null;closeDialog();fn?.();break;}
 case 'new-game':newGameDialog();break;
 case 'guide-route':{const r=JSON.parse(d.route);if(r.type==='command')runAction(r.command);else if(r.type==='life-action')runAction({type:r.action});else dispatch({dataset:{action:r.type,tab:r.tab,product:r.product}});break;}
 case 'goals':openDialog('选择小目标',renderGoals(state,guideContext()));break;
 case 'set-goal':commit(setGoal(state,d.goal));closeDialog();notify('新的阶段目标已记下。');break;
 case 'toggle-watch':{let next=state;if(isOptionMarket(d.product)&&state.journey?.watchlist.some(isOptionMarket)){for(const key of state.journey.watchlist.filter(isOptionMarket))next=toggleWatch(next,key);}else next=toggleWatch(next,marketMenuKey(d.product));commit(next);break;}
 case 'browse-markets':document.querySelector('.market-filters')?.scrollIntoView({block:'start'});break;
 case 'unavailable-story':commit(leaveUnavailableEvent(state,catalog));notify('这件事当前无法参与，已留在小记里。');break;
 case 'home':if(state)persist();closeDialog();state=null;render();scrollGameTo(0);break;
 case 'load-slot':loadGame(Number(d.slot));break;
 case 'birth-next':{commit(advanceBirthPage(state,Number(d.page)));document.querySelector('#birth-title')?.focus({preventScroll:true});break;}
 case 'birth-skip':{commit(skipBirth(state,catalog));focusStory();break;}
 case 'birth-finish':{if(isBirthIntro(state)&&state.phase==='result'){commit(continueChildhood(state,catalog));scrollGameTo(0);}break;}
 case 'choose':{tab='life';const next=chooseEvent(state,d.event,d.choice,catalog);commit(next);sound();focusStory();break;}
 case 'continue':commit(state.age<18?continueChildhood(state,catalog):continueStory(state,catalog));focusStory();break;
 case 'dismiss-milestone':commit(dismissPresentation(state,d.id));break;
 case 'market-filter':{marketFilter=d.filter;render();document.querySelector(`[data-action=market-filter][data-filter=${marketFilter}]`)?.focus({preventScroll:true});break;}
 case 'market-practice':runAction({type:'market_practice'});break;
 case 'market-rules':if(readMarketNotice(state,d.product)){persist();render();}marketRulesDialog(d.product);break;
 case 'child-fast-forward':{closeDialog();commit(continueChildhood(state,catalog,{fast:true}));break;}
 case 'child-settings':{tab='life';render();const details=document.querySelector('.childhood-path');if(details){details.open=true;details.scrollIntoView({block:'center',behavior:'instant'});details.querySelector('summary').focus({preventScroll:true});}break;}
 case 'child-market':{tab='life';render();const target=document.querySelector('.child-market')||document.querySelector('.story-panel');target?.scrollIntoView({block:'start',behavior:'instant'});target?.querySelector('button:not([disabled])')?.focus({preventScroll:true});if(!document.querySelector('.child-market'))notify('先选完当前故事，再去摆摊。');break;}
 case 'child-command':runAction(JSON.parse(d.command));break;
 case 'chapter-preview':case 'stage-return':detailedDay=false;marketDesk=null;tab='life';closeDialog();render();scrollGameTo(0);break;
 case 'stage-focus':{commit(act(state,{type:'stage_plan',focus:d.focus},catalog));if(!state.lastResult?.error){notify('已记下，将从接下来的日子开始执行。');document.querySelector('.stage-footer [data-action=stage-detail]')?.focus({preventScroll:true});}break;}
 case 'stage-detail':closeDialog();tab='life';dailyRoutine();break;
 case 'chapter-start':void runChapterTransition();break;
 case 'chapter-settle-day':void runChapterTransition({settleDay:true});break;
 case 'loan-amount':{const form=button.closest('#loan-form');if(form){form.querySelector('[name=amount]').value=Number(d.amount)/100;updateForm(form);}break;}
 case 'chapter-stop':chapterStopRequested=true;break;
 case 'chapter-receipt':if(state.chapterSummary)openDialog('阶段进展',renderChapterReceipt(state,state.chapterSummary,guideContext()),true);break;
 case 'chapter-bills-more':{const top=dialog.querySelector('.dialog-body')?.scrollTop||0;openDialog('日常消费账单',renderChapterBills(state,{...guideContext(),limit:Math.min(20000,Number(d.limit)||40)}),true);dialog.querySelector('.dialog-body').scrollTop=top;break;}
 case 'chapter-bills':openDialog('日常消费账单',renderChapterBills(state,guideContext()),true);break;
 case 'chapter-return':detailedDay=false;closeDialog();tab='life';render();scrollGameTo(0);break;
 case 'chapter-assets':closeDialog();tab='assets';render();break;
 case 'life-continue':continueLife(false);break;
 case 'day-routine':dailyRoutine();break;
 case 'student-jobs':openDialog('兼职与日程',renderDailyRoutine(state,{esc,icon,money})+(fromRescue?rescueBackLink():''));break;
 case 'day-rules':openDialog('作息与状态',renderDailyStatus(state,{esc,icon,money}));break;
 case 'day-continue':closeDialog();continueLife(false);if(state.dayRoutine?.pending)dailyRoutine();break;
 case 'day-command':{const before=state;runAction({type:d.kind,choice:d.choice,...(d.day!==undefined?{day:Number(d.day),stage:Number(d.stage)}:{})});if(state!==before&&state.phase==='planning'){if(d.kind==='day_activity'&&marketActivity(d.choice)&&!state.dayRoutine?.pending){openDailyMarket();}else{tab='life';closeDialog();render();if(detailedDay)dailyRoutine();}}break;}
 case 'daily-market':openDailyMarket();break;
 case 'next-turn':continueLife(true);break;
 case 'life-away':detailedDay=false;tab='life';closeDialog();render();break;
 case 'living-plan':openDialog('调整日常开支',renderLivingPlan(state,{money,esc})+(fromRescue?rescueBackLink():''));updateLivingPlan(dialog.querySelector('form'),state,{money});break;
 case 'life-hub':openPeople(null,peopleDirectory(state,catalog).counts.promises?'promises':'all');break;
 case 'life-collection':openDialog('过往经历',`<div class="life-history">${(collection.lifeMemories||[]).slice().reverse().map(h=>`<article><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p></article>`).join('')||'<p>还没有记录。</p>'}</div>`,true);break;
 case 'life-scene':openLifeScene();break;
 case 'life-rebuild':if(fromRescue)rescueReturnPage={runId:state.id,tab:'people'};openPeople(null,'work');break;
 case 'people-open':openPeople(d.personId||null);break;
 case 'people-select':peopleView.selectedId=d.personId;peopleView.feedback=null;render();document.querySelector('#contact-name')?.focus({preventScroll:true});break;
 case 'people-filter':peopleView.filter=d.filter;peopleView.feedback=null;render();document.querySelector(`[data-action=people-filter][data-filter=${peopleView.filter}]`)?.focus({preventScroll:true});break;
 case 'family-budget-open':openDialog('两个人的约会预算',renderRomanceBudget(state,{money}));break;
 case 'family-wedding-open':openDialog('你和林夏的婚礼方案',renderWeddingPlan(state,{money,esc}),true);updateWeddingPlan(dialog.querySelector('form'),state,{money});break;
 case 'family-command':runAction(JSON.parse(d.command));if(['family_start','family_topic'].includes(JSON.parse(d.command).type)&&state.lifeArcs?.pending==='family')openLifeScene();break;
 case 'people-command':runAction(JSON.parse(d.command),d.personId);break;
 case 'life-command':{const action=JSON.parse(d.command);runAction(action);if(action.scene==='family'&&action.choice==='plan'&&state.familyLife?.stage==='engaged'){openDialog('你和林夏的婚礼方案',renderWeddingPlan(state,{money,esc}),true);updateWeddingPlan(dialog.querySelector('form'),state,{money});}break;}
 case 'life-legacy':{const a=available({type:'life_succession'});openDialog('把人生交接清楚',`<p>用 1 点精力整理交接清单，资产和债务暂不转移。</p><button class="button primary" data-action="life-command" data-command="${esc(JSON.stringify({type:'life_succession'}))}" ${a.allowed?'':'disabled'}>写好交接清单</button><p>${esc(a.reason||'')}</p>`);break;}
 case 'advance-period':{if(dialog.open)closeDialog();if(timePreview(state).dayMode&&state.phase==='planning'){runAction({type:'survival_day'});break;}marketDesk=null;tab='life';const before=getMetrics(state),oldAge=state.age;const previousLegal=getLegalStatus(state),previousResolved=previousLegal.cases.filter(c=>c.settled).length;commit(nextTurn(state,catalog));if(state.phase==='planning'&&state.age>=18&&!getLegalStatus(state).inPrison){tab='market';render();}if(state.age!==oldAge){const after=getMetrics(state);notify(`${ageText(state.age)}了 · 现金 ${after.cash-before.cash>=0?'+':''}${money(after.cash-before.cash,true)}`);sound();const currentLegal=getLegalStatus(state);if(currentLegal.cases.filter(c=>c.settled).length>previousResolved){const c=currentLegal.cases.filter(c=>c.settled).at(-1);legalCaseDialog(c.id);}else if(previousLegal.inPrison&&!currentLegal.inPrison){openDialog('门外，已经是另一年',`<p class="result-dialog-text">刑期已经服完。你可以重新求职、做生意，慢慢修复关系。尚未履行的退赔和原有借款仍在账本里。</p><button class="button primary full" data-action="close-dialog">看看接下来的日子 ${icon('arrow')}</button>`);}}break;}
 case 'tab':if(dialog.open)closeDialog();tab=d.tab;if(tab==='life')detailedDay=false;render();if(tab==='people')scrollPeoplePage();else document.querySelector('#main-content')?.scrollIntoView({block:'start',behavior:'instant'});break;
 case 'job-select':jobDialog(d.id);break;
 case 'job-accept':runAction({type:'job_accept',offerId:d.id});break;
 case 'job-offers':jobDialog();break;
 case 'life-action':runAction({type:d.type});break;
 case 'invest':case 'desk-open':if(!marketIsOpen(state,d.product)){if(readMarketNotice(state,d.product)){persist();render();}marketRulesDialog(d.product);break;}if(offerMarketWelcome(d))break;marketReturn={top:document.querySelector('.market-directory')?(document.querySelector('.game-scroll')?.scrollTop||0):0,product:d.product};marketDesk=d.product;deskSelection=d.instrument||null;cryptoMode=d.mode||'spot';tab='market';render();if(d.area)jumpWithinDesk(d.area);else document.querySelector('.market-desk')?.scrollIntoView({block:'start',behavior:'instant'});break;
 case 'market-intro-rules':openDialog(marketWelcome(state,d.product)?.title||'市场介绍',renderMarketWelcome(state,d.product,{esc},true));break;
 case 'market-intro-enter':{if(!marketIsOpen(state,d.product))break;state=structuredClone(state);state.flags['market_intro_'+welcomeKey(d.product)]=true;persist();const entry={...(pendingMarketEntry||{}),action:'desk-open',product:d.product};pendingMarketEntry=null;closeDialog();dispatch({dataset:entry});break;}
 case 'desk-jump':jumpWithinDesk(d.area);break;
 case 'desk-life-preview':{const body=renderTimePanel(state,guideContext());openDialog('待结账单',body||'<p>先处理眼前的故事，再继续人生。</p>');const preview=dialog.querySelector('.time-preview');if(preview)preview.open=true;break;}
 case 'desk-back':marketDesk=null;deskSelection=null;render();scrollGameTo(marketReturn.top);document.querySelector(`.market-row[data-market="${CSS.escape(marketMenuKey(marketReturn.product||''))}"] .market-row-actions .button`)?.focus({preventScroll:true});break;
 case 'stock-market':deskSelection=d.id;render();document.querySelector(`[data-action=stock-market][data-id="${d.id}"]`)?.focus({preventScroll:true});break;
 case 'desk-instrument':deskSelection=d.id;render();break;
 case 'gambling-game':deskSelection=d.game;render();document.querySelector('.casino-games .selected')?.focus({preventScroll:true});break;
 case 'go-work':{closeDialog();tab='life';render();const target=document.querySelector('.arrangements');const fold=target?.closest('details');if(fold)fold.open=true;target?.scrollIntoView({block:'center',behavior:'instant'});(target?.querySelector('[data-type=work]:not([disabled]),[data-type=gig]:not([disabled])')||target?.querySelector('button:not([disabled])'))?.focus({preventScroll:true});break;}
 case 'desk-budget':{const form=document.querySelector('#desk-order'),cap=Math.floor(state.cash*Number(d.fraction)),max=maximumOrder(cap,{product:form.dataset.product,instrument:form.dataset.instrument,price:Number(form.dataset.price)}),input=form.querySelector('[name=lots],[name=amount]');input.value=form.dataset.product==='stock'?String(max.lots):(max.amount/100).toFixed(2);updateDeskForm(form,state,{money,esc});break;}
 case 'gambling-stake':{const form=document.querySelector('#gamble-form'),input=form.querySelector('[name=amount]');input.value=(Math.floor(state.cash*(d.fraction==='all'?1:Number(d.fraction)))/100).toFixed(2);updateDeskForm(form,state,{money,esc});break;}
 case 'option-side':if(isOptionMarket(d.product)){marketDesk=d.product;render();document.querySelector('.option-sides [aria-pressed=true]')?.focus({preventScroll:true});}break;
 case 'crypto-ledger-tab':if(['trades','news'].includes(d.view)){const records=document.querySelector('.crypto-records');if(records){cryptoLedgerTab=d.view;records.outerHTML=renderCryptoRecords(state,cryptoMode,{esc,money,cryptoLedgerTab});document.querySelector(`.crypto-ledger-tabs [data-view="${d.view}"]`)?.focus({preventScroll:true});}}break;
 case 'crypto-mode':cryptoMode=d.mode;deskSelection=null;render();break;
 case 'desk-command':runAction(JSON.parse(d.command));break;
 case 'desk-lots':{const input=document.querySelector('#desk-order [name=lots]');input.value=Math.max(1,Number(input.value)+Number(d.delta));updateDeskForm(input.form,state,{money,esc});break;}
 case 'invest-fraction':{const input=dialog.querySelector('#amount');if(input){const min=PRODUCTS[dialog.querySelector('form').dataset.product].min;const amount=Math.floor(state.cash*Number(d.fraction));input.value=(amount/100).toFixed(2);updateForm(input.form);}break;}
 case 'business':businessDialog();break;
 case 'loans':loansDialog(d.kind);break;
 case 'rescue-options':rescueDialog();break;
 case 'hospital-options':openDialog('住院治疗',renderHospitalDialog(state,guideContext()));break;
 case 'rescue-assets':rescueReturnPage={runId:state.id,tab:'assets'};closeDialog();tab='assets';render();document.querySelector('#main-content')?.scrollIntoView({block:'start',behavior:'instant'});break;
 case 'repay':repayDialog(d.id);break;
 case 'behavior-hub':behaviorHub();break;
 case 'behavior-scene':behaviorScene();break;
 case 'behavior-do':runAction(JSON.parse(d.command));break;
 case 'debt-calendar':debtCalendarDialog();break;
 case 'debt-extend':{const q=getDebtExtension(state,d.id);if(q.reason){notify(q.reason);break;}confirmDialog('申请把还款日往后挪',`推迟 30 天，立即支付费用 ${money(q.fee)}，另增加利息 ${money(q.interest)}。本金与旧欠款仍保留。`,()=>runAction({type:'debt_extend',id:d.id}),'按这些条件展期');break;}
 case 'sell':{const p=[...state.positions,...state.businesses].find(x=>x.id===d.id);if(!p)return;const exit=assetExit(state,p);if(!exit.allowed){notify(exit.reason);break;}confirmDialog(`确认${exit.label}`,`${exit.label}“${p.name}”，当前账面 ${money(p.value)}。${exit.cost}。成交会扣除对应费用；抵押资产先偿还关联欠款，资金盘可能无法兑付。`,()=>runAction(exit.action),'确认'+exit.label);break;}
 case 'claim':runAction({type:'claim',id:d.id});break;
 case 'relationship':runAction({type:'relationship',kind:d.kind});break;
 case 'exit-risk':runAction({type:'exit_risk'});break;
 case 'settle':confirmDialog('翻一翻，这一路的人生',`在 ${ageText(state.age)} 留下一篇后记。现有资产与欠款会保留，80 岁前还可以接着过日子。`,()=>commit(settleRun(state,catalog)),'看看我的后记');break;
 case 'resume':tab='life';commit(resumeRun(state,catalog));break;
 case 'saves':savesDialog();break;
 case 'save-to-slot':{const slot=Number(d.slot),s=listSlots()[slot];const perform=()=>{saveSlot(slot,state);activeSlot=slot;notify('已经记在这本档案里。');savesDialog();};if(s.state||s.error)confirmDialog('替换这本人生档案',`当前人生将替换档案 ${slot+1} 的内容，其他档案不受影响。`,perform,'替换档案');else perform();break;}
 case 'delete-slot':{const slot=Number(d.slot);confirmDialog('删除这本档案',`档案 ${slot+1} 将从当前浏览器移除。已导出的文件不受影响；这一操作无法撤销。`,()=>{removeSlot(slot);if(state&&activeSlot===slot){state=null;render();}savesDialog();},'删除这本档案');break;}
 case 'export-slot':exportSlot(Number(d.slot));break;
 case 'import':importSlot=Number(d.slot);document.querySelector('#import-file').click();break;
 case 'export-journal':exportJournal();break;
 case 'settings':settingsDialog();break;
 case 'playtest':openDialog('试玩反馈',renderPlaytest()+`<p>已记录 ${collection.playtests.length} 次自填反馈</p><button class="text-button" data-action="export-playtest">导出本地试玩记录</button>`);break;
 case 'export-playtest':downloadFile('中国式赌狗-自填试玩记录.json',JSON.stringify(collection.playtests,null,2));break;
 case 'help':helpDialog();break;
 case 'character':openDialog('人物资料',sidebar(true));break;
 case 'history-filter':historyFilter=d.key;render();break;
 case 'journal-filter':journalFilter=d.key;render();break;
 case 'history-detail':historyDetail(d.id);break;
 case 'legal-case':legalCaseDialog(d.id);break;
 case 'turn-detail':{const r=state.lastTurnSummary;if(r)openDialog(`${ageText(r.fromAge)} → ${ageText(r.toAge)} 的账本`,`<p class="dialog-intro">本期 ${r.months} 个月，已结账。</p><div class="turn-note-list">${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div><button class="button full" data-action="close-dialog">合上账本</button>`);break;}
 case 'ending-collection':endingCollection();break;
 case 'ending-detail':endingDetail(d.id);break;
 case 'retry':boot();break;
}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;try{dispatch(button);}catch(error){notify('这一步没能完成：'+error.message);console.error(error);}});
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();try{if(form.id==='family-wedding-form'){runAction(weddingFormAction(form));}else if(form.id==='living-plan-form'){runAction(livingPlanAction(form));}else if(form.id==='playtest-form'){collection=savePlaytest(state,Object.fromEntries(new FormData(form)));closeDialog();notify('试玩记录已保存在本机，可从档案导出');}else if(form.id==='new-game-form'){const d=new FormData(form),slot=Number(d.get('slot'));const options={name:String(d.get('name')).trim()||'阿财',mode:d.get('mode'),startAt:d.get('startAt'),childhood:d.get('childhood'),birthYear:Number(d.get('birthYear')),seed:String(d.get('seed')).trim()||crypto.randomUUID(),familyId:d.get('familyId')||undefined};const saved=listSlots()[slot];if(saved.state||saved.error)confirmDialog('覆盖已有存档',`开始后会替换档案 ${slot+1}。若要保留旧人生，请先取消并导出存档。`,()=>beginNewRun(options,slot),'开始新人生');else beginNewRun(options,slot);}else if(form.id==='child-market-form'){const d=new FormData(form);runAction({type:'child_buy',good:d.get('good'),quantity:Number(d.get('quantity'))});}else if(form.matches('#desk-order,#gamble-form,.desk-manage-form')){runAction(deskFormAction(form));}else{const action=actionFromForm(form);if(action&&confirmAvailability(form,action))runAction(action);}}catch(error){const box=form.querySelector('.form-error');if(box)box.textContent=error.message;else notify(error.message);}});
document.addEventListener('pointerdown',noteTradeInput,true);
document.addEventListener('keydown',noteTradeInput,true);
document.addEventListener('focusin',event=>keepTradeFocusVisible(event.target));
document.addEventListener('input',event=>updateForm(event.target.closest('form')));
document.addEventListener('change',event=>{const input=event.target;if(input.id==='child-focus'){state=structuredClone(state);state.childhood.focus=input.value;persist();const label=document.querySelector('[data-child-focus-label]');if(label)label.textContent=input.selectedOptions[0].textContent;return;}if(input.id==='start-at'){document.querySelector('#childhood-focus').hidden=input.value!=='teen';return;}if(input.id==='desk-switch'){if(!marketIsOpen(state,input.value)){const product=input.value;input.value=marketDesk;if(readMarketNotice(state,product)){persist();render();}marketRulesDialog(product);return;}if(offerMarketWelcome({product:input.value})){input.value=marketDesk;return;}marketDesk=input.value;deskSelection=null;cryptoMode='spot';render();return;}if(input.dataset.setting){settings[input.dataset.setting]=input.checked;setSettings(settings);document.documentElement.classList.toggle('reduce-motion',settings.reduced);if(input.dataset.setting==='sound')sound('good');}if(input.id==='loan-kind'){const offer=getLoanOffer(state,input.value);input.form.querySelector('[name=amount]').value=offer.principal/100;}if(input.name==='mode')document.querySelector('#birth-year-field').hidden=input.value!=='history';if(input.name==='familyId'){const f=catalog.families.find(x=>x.id===input.value);document.querySelector('#family-description').textContent=f?`${f.opening} 成年赠与 ¥${f.adult_gift_yuan[0].toLocaleString()}–${f.adult_gift_yuan[1].toLocaleString()}。${f.constraint}`:'12 种家庭，成年赠与与家中储备分别抽取。';}if(input.name==='slot'){const s=listSlots()[Number(input.value)];document.querySelector('#new-game-warning').hidden=!s.state&&!s.error;}updateForm(input.closest('form'));});
document.querySelector('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>8*1024*1024)throw Error('文件过大，请选择 8 MB 以内的游戏存档。');const imported=decodeSave(await file.text());const target=importSlot;const use=()=>{saveSlot(target,imported);loadGame(target);};const existing=listSlots()[target];if(existing.state||existing.error)confirmDialog('导入这一段人生',`${imported.name}，${ageText(imported.age)}。导入将替换档案 ${target+1}。`,use,'导入并继续');else use();}catch(error){notify('没有导入：'+error.message);}});
document.addEventListener('keydown',event=>{if(dialog.open||isNightTransitionActive()||document.querySelector('#game-info,.game-choice-list,#trade-inbox')||event.altKey||event.ctrlKey||event.metaKey||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName))return;if(state?.phase==='event'&&tab==='life'&&/^[1-9]$/.test(event.key)){event.preventDefault();document.querySelectorAll('.choice')[Number(event.key)-1]?.click();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
dialog.addEventListener('cancel',event=>{event.preventDefault();closeDialog();});
dialog.addEventListener('close',()=>queueMicrotask(maybeRescueDialog));
window.addEventListener('resize',()=>{if(tab==='assets'&&state)drawChart();});
bindDailyCharts();
async function boot(){try{const names=['events','families','history','endings','characters'];const data=await Promise.all(names.map(async name=>{const r=await fetch(`./data/${name}.json`);if(!r.ok)throw Error(`${name} 数据加载失败`);return r.json();}));catalog=Object.fromEntries(names.map((n,i)=>[n,n==='events'?data[i].events:data[i]]));setSaveCatalog(catalog);render();}catch(error){app.innerHTML=`<main class="boot"><strong>人生档案还没加载好</strong><p>${esc(error.message)}</p><button class="button primary" data-action="retry">再试一次</button><small>请通过本地启动器打开游戏，保持页面与 data 文件夹在一起。</small></main>`;console.error(error);}}
initGameControls();
boot();

const caseNames={gambling:'网络赌博参与记录',gambling_promotion:'明知参与网赌推广',account_rental:'明知出租账户协助犯罪',fraud:'明知参与欺诈项目',data_resale:'违法买卖个人信息',illegal_fundraising:'参与非法集资',misleading_ads:'误导营销'};
const caseStatuses={pending:'涉险行为记录',exposed:'相关线索出现',investigating:'正在调查',convicted:'已作刑事判决',admin_closed:'已作行政处理'};
function prisonDuration(months){const years=Math.floor(months/12),rest=months%12;return [years?years+'年':'',rest?rest+'个月':''].filter(Boolean).join('')||'0个月';}
function legalBanner(){const l=getLegalStatus(state);if(!l.inPrison&&!l.underInvestigation&&!l.legalDebt)return '';return `<button class="legal-banner ${l.inPrison?'incarcerated':''}" data-action="tab" data-tab="legal">${icon(l.inPrison?'lock':'scales')}<span><strong>${l.inPrison?'正在服刑 · 剩余 '+prisonDuration(l.prisonMonthsLeft):l.underInvestigation?'有案件正在调查':'这段人生，还有责任待履行'}</strong><small>${l.inPrison?'外部工作、经营和交易安排暂停；已有债务与被动持仓继续结算。':l.legalDebt?'尚有 '+money(l.legalDebt,true)+' 罚款、退赔或追缴款待支付。':'案件仍在推进，调查不等于已经定罪。'}</small></span>${icon('chevron')}</button>`;}
function prisonPlanning(){const l=getLegalStatus(state);return `<section class="story-panel prison-planning"><div class="story-kicker"><span>${icon('lock')} 这一页，慢慢过</span><span>精力 ${state.actionPoints} / 2</span></div><h2>这一次，亏掉的是时间。</h2><p class="story-text">还剩 ${prisonDuration(l.prisonMonthsLeft)}。过去的选择已经留下后果，眼前仍可以学一点东西，写一封信，把出狱后的第一步想清楚。</p><div class="prison-clock"><span>累计已经服刑</span><strong>${prisonDuration(l.servedPrisonMonths)}</strong><span>这期将经过 ${getTurnMonths(state)} 个月</span></div><button class="button primary next-turn" data-action="next-turn">日历再翻 ${getTurnMonths(state)} 个月 ${icon('arrow')}</button>${state.age>=55?'<button class="text-button settle-link" data-action="settle">看看这一生已经留下什么</button>':''}</section>`;}
function renderLegal(){const l=getLegalStatus(state),cooperate=available({type:'legal_cooperate'}),quit=available({type:'quit_gambling'});return `<section class="workspace legal-workspace">${workspaceHead('scales','人生案卷','')}<div class="legal-overview"><span class="legal-seal">${icon(l.inPrison?'lock':'scales')}</span><div><strong>${l.inPrison?'服刑中':l.underInvestigation?'调查尚未结束':l.releaseCount?'门外的日子，重新开始':l.cases.length?'这些事，已经记进人生':'这页暂时空着'}</strong><p>${l.inPrison?'剩余 '+prisonDuration(l.prisonMonthsLeft)+'；服刑期间不能安排外部交易与工作。':l.releaseCount?'服刑结束不会抹掉未付的退赔和原有借款。':'按时间查看调查、裁定和待付账单。'}</p></div></div>${l.cases.length?`<div class="balance-strip legal-balances"><div><span>待付罚款</span><strong>${money(l.unpaidPenalty,true)}</strong></div><div><span>待付退赔</span><strong>${money(l.unpaidRestitution,true)}</strong></div><div><span>待追缴所得</span><strong>${money(l.unpaidConfiscation,true)}</strong></div></div>`:''}<div class="legal-actions">${l.underInvestigation?`<button class="button small" data-action="life-action" data-type="legal_cooperate" ${cooperate.allowed?'':'disabled'}>如实配合调查</button><span>${cooperate.allowed?'提交调查说明。':esc(cooperate.reason)}</span>`:''}${state.flags.gambling_history&&!state.flags.gambling_quit?`<button class="button small" data-action="life-action" data-type="quit_gambling" ${quit.allowed?'':'disabled'}>停止参赌，重排生活</button><span>${quit.allowed?'停止参赌，旧案继续处理。':esc(quit.reason)}</span>`:''}${l.legalDebt&&!l.inPrison?'<button class="text-button" data-action="repay">安排偿还欠款 →</button>':''}</div><div class="case-list">${l.cases.length?l.cases.slice().reverse().map(c=>`<button class="case-row" data-action="legal-case" data-id="${esc(c.id)}"><span class="case-number">${icon(c.status==='convicted'?'lock':'book')}</span><span class="case-main"><strong>${esc(caseNames[c.type]||c.type)}</strong><small>第 ${c.openedTurn+1} 回合留下的记录 · ${esc(caseStatuses[c.status]||c.status)}</small>${c.settled?`<small>${c.sentenceMonths?'判处游戏刑期 '+prisonDuration(c.sentenceMonths)+' · ':''}罚款 ${money(c.fine,true)} · 退赔 ${money(c.restitution,true)}</small>`:'<small>尚未裁定，不能把调查记录当作既定判决。</small>'}</span>${icon('chevron')}</button>`).join(''):empty('有些快钱，可以不伸手','成年后会在故事中遇到网赌与灰黑产的诱惑。参与、拒绝、及时停止，会写出不同的后续。')}</div><p class="workspace-footnote">案情和刑期为虚构剧情。</p></section>`;}
function legalCaseDialog(id){const c=getLegalStatus(state).cases.find(c=>c.id===id);if(!c)return;const balance=state.debts.filter(d=>d.legalCaseId===c.id).reduce((sum,d)=>sum+d.principal+d.interest,0);const steps=[['行为记录',c.openedTurn,true],['出现线索',c.exposedTurn,['exposed','investigating','convicted','admin_closed'].includes(c.status)],['案件调查',c.investigatingTurn,['investigating','convicted','admin_closed'].includes(c.status)],['处理结果',c.resolvedTurn,c.settled]];openDialog(caseNames[c.type]||'这一次选择的后果',`<div class="case-status-title">${icon(c.status==='convicted'?'lock':'scales')}<span>${esc(caseStatuses[c.status])}</span></div><div class="case-timeline">${steps.map(([label,turn,done])=>`<div class="case-step ${done?'done':''}"><span></span><strong>${label}</strong><small>${done&&turn!=null?'第 '+(turn+1)+' 回合':'尚未发生'}</small></div>`).join('')}</div>${c.settled?`<p class="result-dialog-text">${c.sentenceMonths?`判处游戏刑期 ${prisonDuration(c.sentenceMonths)}。`:'这次按行政情节作出处理，没有形成刑事服刑。'}</p><dl class="case-bill"><div><dt>追缴违法所得</dt><dd>${money(c.confiscation)}</dd></div><div><dt>${c.sentenceMonths?'罚金':'罚款'}</dt><dd>${money(c.fine)}</dd></div><div><dt>退赔责任</dt><dd>${money(c.restitution)}</dd></div><div class="total"><dt>目前尚欠本息</dt><dd>${money(balance)}</dd></div></dl><p class="field-help">先用现金支付，差额记为欠款。服刑不抵扣欠款。</p>`:`<p class="result-dialog-text">当时入账 ${money(c.profit)}。目前${esc(caseStatuses[c.status])}，尚未作出处理结果。</p>`}${c.cooperated?'<p class="field-help">已如实配合调查。</p>':''}<p class="workspace-footnote">案情和刑期为虚构剧情。</p><button class="button primary full" data-action="close-dialog">关闭案卷 ${icon('book')}</button>`);}

document.addEventListener('change',event=>{const form=event.target.closest('#family-wedding-form');if(form)updateWeddingPlan(form,state,{money});});
